import * as THREE from 'three';
import { createScene } from './data/object.js';
import * as fs from 'fs';

// Create the scene
const scene = createScene();

// Prepare output data
const vertices = [];
const faces = [];
let vertexOffset = 1; // OBJ format uses 1-based indexing

// Matrix for converting Y-up (Three.js) to Z-up (Blender)
// This is a -90 degree rotation around X axis
const yUpToZUp = new THREE.Matrix4();
yUpToZUp.makeRotationX(-Math.PI / 2);

// Traverse the scene and extract geometry
scene.traverse((object) => {
  if (object instanceof THREE.Mesh) {
    // Get world matrix for this object
    object.updateWorldMatrix(true, false);
    const worldMatrix = object.matrixWorld.clone();

    // Apply Y-up to Z-up conversion
    const finalMatrix = new THREE.Matrix4();
    finalMatrix.multiplyMatrices(yUpToZUp, worldMatrix);

    const geometry = object.geometry;

    // Clone geometry to avoid modifying original
    const geo = geometry.clone();

    // Apply the transformation matrix to the geometry
    geo.applyMatrix4(finalMatrix);

    // Extract vertices
    const positions = geo.attributes.position;
    const startVertex = vertexOffset;

    for (let i = 0; i < positions.count; i++) {
      const x = positions.getX(i);
      const y = positions.getY(i);
      const z = positions.getZ(i);
      vertices.push(`v ${x} ${y} ${z}`);
    }

    // Extract faces
    if (geo.index) {
      // Indexed geometry
      const indices = geo.index;
      for (let i = 0; i < indices.count; i += 3) {
        const a = indices.getX(i) + startVertex;
        const b = indices.getX(i + 1) + startVertex;
        const c = indices.getX(i + 2) + startVertex;
        faces.push(`f ${a} ${b} ${c}`);
      }
    } else {
      // Non-indexed geometry
      for (let i = 0; i < positions.count; i += 3) {
        const a = i + startVertex;
        const b = i + 1 + startVertex;
        const c = i + 2 + startVertex;
        faces.push(`f ${a} ${b} ${c}`);
      }
    }

    vertexOffset += positions.count;
  } else if (object instanceof THREE.InstancedMesh) {
    // Handle instanced meshes
    const instanceCount = object.count;
    const geometry = object.geometry;

    // Get world matrix for the InstancedMesh object itself
    object.updateWorldMatrix(true, false);
    const baseWorldMatrix = object.matrixWorld.clone();

    for (let instanceId = 0; instanceId < instanceCount; instanceId++) {
      // Get the instance matrix
      const instanceMatrix = new THREE.Matrix4();
      object.getMatrixAt(instanceId, instanceMatrix);

      // Combine base world matrix with instance matrix
      const worldMatrix = new THREE.Matrix4();
      worldMatrix.multiplyMatrices(baseWorldMatrix, instanceMatrix);

      // Apply Y-up to Z-up conversion
      const finalMatrix = new THREE.Matrix4();
      finalMatrix.multiplyMatrices(yUpToZUp, worldMatrix);

      // Clone geometry to avoid modifying original
      const geo = geometry.clone();

      // Apply the transformation matrix to the geometry
      geo.applyMatrix4(finalMatrix);

      // Extract vertices
      const positions = geo.attributes.position;
      const startVertex = vertexOffset;

      for (let i = 0; i < positions.count; i++) {
        const x = positions.getX(i);
        const y = positions.getY(i);
        const z = positions.getZ(i);
        vertices.push(`v ${x} ${y} ${z}`);
      }

      // Extract faces
      if (geo.index) {
        // Indexed geometry
        const indices = geo.index;
        for (let i = 0; i < indices.count; i += 3) {
          const a = indices.getX(i) + startVertex;
          const b = indices.getX(i + 1) + startVertex;
          const c = indices.getX(i + 2) + startVertex;
          faces.push(`f ${a} ${b} ${c}`);
        }
      } else {
        // Non-indexed geometry
        for (let i = 0; i < positions.count; i += 3) {
          const a = i + startVertex;
          const b = i + 1 + startVertex;
          const c = i + 2 + startVertex;
          faces.push(`f ${a} ${b} ${c}`);
        }
      }

      vertexOffset += positions.count;
    }
  }
});

// Write OBJ file
const objContent = [
  '# OBJ file exported from Three.js',
  '# Converted to Blender Z-up coordinate system',
  '',
  ...vertices,
  '',
  ...faces
].join('\n');

fs.writeFileSync('/root/output/object.obj', objContent);

console.log(`Export complete!`);
console.log(`Vertices: ${vertices.length}`);
console.log(`Faces: ${faces.length}`);
console.log(`Output: /root/output/object.obj`);
EOF
",
      "duration": 0.1
    }
  ]
}

